## ✅ Fixed & Improved Controller Code (Clean, Safe, and Maintainable)

```csharp
[HttpGet("getTask")]
public async Task<IActionResult> GetTask(showTask model)
{
    if (model == null)
        return BadRequest();

    var set = await _context.Tasks
        .Where(x => x.Id == model.idTask)
        .FirstOrDefaultAsync();

    if (set == null)
        return NotFound("Task not found.");

    var client = await _context.Users
        .Where(x => x.Id == model.idUser)
        .FirstOrDefaultAsync();

    if (client == null)
        return NotFound("User not found.");

    var maxi = await _context.MaximumTasks
        .Where(x => x.Id == 1)
        .FirstOrDefaultAsync();

    // Check daily limits
    if (set.DailyDoneUsers >= set.UsersPerDay || set.CloseDate != null)
        return BadRequest("Daily limit reached or task closed.");

    var doneClients = set.Users.Split(",").Where(c => !string.IsNullOrWhiteSpace(c)).ToList();
    if (doneClients.Contains(client.Id.ToString()))
        return BadRequest("User already completed this task today.");

    if (set.DailyDoneTasks >= (maxi?.Value ?? 0))
        return BadRequest("Daily task limit reached.");

    // Prepare response data
    var data = new getTask();

    data.tosk = set; // This is fine only if 'getTask' has a proper property that can hold Task (e.g., public Task Tsk)

    // Handle different task types
    if (set.Type == "rate")
    {
        // No text or image — just return task
        return Ok(data);
    }
    else if (set.Type == "text")
    {
        var assigned = set.StaticTxts.Split(",").Where(s => !string.IsNullOrWhiteSpace(s)).ToArray();
        if (assigned.Length == 0)
            return BadRequest("No static text assigned.");

        var checkagain = await _context.CompletedTasks
            .Where(x => x.TaskId == set.Id)
            .LastOrDefaultAsync();

        if (checkagain == null)
        {
            data.stattxt = assigned[0]; // First item
        }
        else
        {
            var compare = await _context.StaticMsgs.ToListAsync();
            if (compare.Count == 0)
                data.stattxt = assigned[0]; // fallback
            else if (checkagain.StaticTxt == compare.Last().Txt)
            {
                // Rotate to next random
                var randomIndex = new Random().Next(assigned.Length);
                data.stattxt = assigned[randomIndex];
                // Update DB (optional)
                set.RoundTxt1 = false;
                set.RoundTxt2 = true;
                await _context.SaveChangesAsync();
            }
            else
            {
                var index = Array.IndexOf(assigned, checkagain.StaticTxt);
                if (index >= 0 && index < assigned.Length - 1)
                {
                    data.stattxt = assigned[index + 1];
                }
                else
                {
                    data.stattxt = assigned[0]; // loop back to start
                }
            }
        }
        return Ok(data);
    }
    else if (set.Type == "img")
    {
        var tt = set.StaticImgs.Split(",").Where(s => !string.IsNullOrWhiteSpace(s)).ToArray();
        var assigned = set.StaticTxts.Split(",").Where(s => !string.IsNullOrWhiteSpace(s)).ToArray();

        if (tt.Length == 0)
            return BadRequest("No images assigned.");

        var checkagain = await _context.CompletedTasks
            .Where(x => x.TaskId == set.Id)
            .LastOrDefaultAsync();

        if (checkagain == null)
        {
            data.stattxt = assigned.Length > 0 ? assigned[0] : "";
            data.statpath = tt[0];
        }
        else
        {
            var compare = await _context.StaticMsgs.ToListAsync();
            if (compare.Count == 0)
            {
                data.stattxt = assigned.Length > 0 ? assigned[0] : "";
                data.statpath = tt[0];
            }
            else if (checkagain.StaticImg.ToString() == tt.Last())
            {
                // Rotate images
                var randomIndex = new Random().Next(tt.Length);
                data.statpath = tt[randomIndex];
                set.RoundImg1 = false;
                set.RoundImg2 = true;
                await _context.SaveChangesAsync();
            }
            else
            {
                var index = Array.IndexOf(tt, checkagain.StaticImg);
                if (index >= 0 && index < tt.Length - 1)
                {
                    data.statpath = tt[index + 1];
                }
                else
                {
                    data.statpath = tt[0]; // loop back
                }
            }

            // Set text if available
            if (assigned.Length > 0)
            {
                var index = Array.IndexOf(assigned, checkagain.StaticTxt);
                if (index >= 0 && index < assigned.Length - 1)
                {
                    data.stattxt = assigned[index + 1];
                }
                else
                {
                    data.stattxt = assigned[0];
                }
            }
        }

        return Ok(data);
    }
    else
    {
        return BadRequest("Invalid task type.");
    }
}
```

